INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Stored Procedures immer schneller als normale Abfragen?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Optimierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Stored Procedures?', 3, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Reduziert Redundanz"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Funktion wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Logik zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten mir Stored Procedures?', 5, '[{"text": "Performance durch Kompilierung", "correct": true, "because": "Vorab optimiert"}, {"text": "Sicherheit durch Parameter", "correct": true, "because": "Schützt vor Injections"}, {"text": "Schnelle Installation", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Syntax", "correct": false, "because": "Kein Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Stored Procedures sind wiederverwendbar. b) Sie ersetzen alle Abfragen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Stored Procedures?', 4, '[{"text": "Parameter", "correct": false, "because": "Sichern Eingaben"}, {"text": "Logik", "correct": false, "because": "Kern der Prozedur"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Stored Procedures auch Sicherheit erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz vor SQL-Injection"}, {"text": "Nein", "correct": false, "because": "Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature wähle ich für wiederholte Aufgaben in Stored Procedures?', 3, '[{"text": "Prozeduraufruf", "correct": true, "because": "Wiederverwendbar"}, {"text": "Manuelle Abfragen", "correct": false, "because": "Weniger effizient"}, {"text": "Tabellenkopien", "correct": false, "because": "Keine Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Stored Procedures effektiv?', 5, '[{"text": "Kompilierte Ausführung", "correct": true, "because": "Schnellere Verarbeitung"}, {"text": "Zentralisierte Logik", "correct": true, "because": "Einfache Wartung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Stored Procedures reduzieren Netzwerkverkehr. b) Sie sind immer einfach zu schreiben. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Stored Procedures?', 4, '[{"text": "SQL-Logik", "correct": false, "because": "Kern der Prozedur"}, {"text": "Parameter", "correct": false, "because": "Sichern Flexibilität"}, {"text": "Spiele-Modus", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Stored Procedures nur für große Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Nützlich unabhängig von Größe"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern Stored Procedures?', 4, '[{"text": "Parameterisierung", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Fehlerbehandlung", "correct": true, "because": "Sichert Robustheit"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Weniger effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Stored Procedures nur für Performance sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Sicherheit und Wartung"}, {"text": "Ja", "correct": false, "because": "Mehrere Vorteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Stored Procedures unwichtig?', 3, '[{"text": "Logikdefinition", "correct": false, "because": "Kern der Funktion"}, {"text": "Aufrufbarkeit", "correct": false, "because": "Wiederverwendung"}, {"text": "Oberflächen-Design", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie sind kompiliert. b) Sie ersetzen alle Skripte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skripte bleiben nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Stored Procedures sicher?', 5, '[{"text": "Parameterprüfung", "correct": true, "because": "Verhindert Injections"}, {"text": "Berechtigungssteuerung", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "Schnelle CPU", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für komplexe Datenbanklogik?', 4, '[{"text": "Stored Procedures", "correct": true, "because": "Zentralisiert Logik"}, {"text": "Manuelle Abfragen", "correct": false, "because": "Weniger wartbar"}, {"text": "Tabellenkopien", "correct": false, "because": "Keine Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Können Stored Procedures Transaktionen enthalten?', 3, '[{"text": "Ja", "correct": true, "because": "Unterstützen ACID"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Stored Procedures wartungsintensiv sind?', 2, '[{"text": "Nein", "correct": true, "because": "Zentralisiert einfacher"}, {"text": "Ja", "correct": false, "because": "Weniger Aufwand"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck erfüllen Stored Procedures am besten?', 4, '[{"text": "Automatisierte Prozesse", "correct": true, "because": "Wiederverwendbare Logik"}, {"text": "Einmalige Abfragen", "correct": false, "because": "Weniger effizient"}, {"text": "Datenlöschung", "correct": false, "because": "Nur ein Aspekt"}]');
